import { useState } from 'react';
import SwipeToast from '../../../.upstream/src/ts-default/Micro/SwipeToast/SwipeToast';
import { DemoPanel } from '../../shared/demo-support';
import styles from '../../shared/micro-demos.module.css';
import {componentClasses} from '../../shared/class-names';
const cn=(names:string)=>componentClasses(styles,names);

export default function SwipeToastDemo() {
  const [open, setOpen] = useState(/*__AW_STATE_state.open__*/);
  const [revision, setRevision] = useState(0);
  const [message, setMessage] = useState('通知已显示，可滑动、关闭或撤销。');
  return <DemoPanel title="Swipe Toast · 可滑动通知"><div className={cn("aw-micro-stack")}>
    <div style={{ minHeight: 150, display: 'flex', alignItems: 'center', maxWidth: '100%' }}><SwipeToast key={revision} title="演示配置已保存" description="这是本地模拟通知。" actionLabel="撤销" open={open} onClose={reason => { setOpen(false); setMessage(`通知已关闭：${reason}`); }} onAction={() => { setMessage('已撤销本地演示操作。'); setOpen(false); }}         /*__AW_PROPS_t0__*/  /></div>
    <div className={cn("aw-micro-controls")}><button className={styles['aw-micro-action']}  onClick={() => { setRevision(value => value + 1); setOpen(true); setMessage('通知已重新显示。'); }} /*__AW_PROPS_t1__*/ >显示通知</button></div>
    <p className={cn("aw-micro-status")} role="status" aria-live="polite">{message}</p>
  </div></DemoPanel>;
}
